package org.solarelevation.alarm;
import android.content.*;
import android.net.*;
import java.io.*;
import java.net.*;
import java.security.*;
import java.util.*;
public final class SolarAlarmDatasets {
public static final String SOURCE_ID="SolarAlarmDatasets_v20261024T225906Z";
public static final String SPK="spk",EOP="eop",LEAP="leap";
private static final String[] TYPES={SPK,EOP,LEAP};
private static final String[] DEFAULTS={"https://naif.jpl.nasa.gov/pub/naif/generic_kernels/spk/planets/de442s.bsp","https://maia.usno.navy.mil/ser7/finals2000A.all","https://data.iana.org/time-zones/data/leap-seconds.list"};
public static String title(String kind){switch(kind){case SPK:return "Planetary ephemeris";case EOP:return "Earth orientation";case LEAP:return "Leap seconds";default:throw new IllegalArgumentException("Unknown dataset "+kind);}}
public static String defaultName(String kind){switch(kind){case SPK:return "de442s.bsp";case EOP:return "finals2000A.all";case LEAP:return "leap-seconds.list";default:throw new IllegalArgumentException("Unknown dataset "+kind);}}
public static String url(String kind){for(int i=0;i<TYPES.length;i++)if(TYPES[i].equals(kind))return DEFAULTS[i];throw new IllegalArgumentException("Unknown dataset type");}
public static File file(Context context,String kind){String suffix=kind.equals(SPK)?".bsp":kind.equals(EOP)?".all":kind.equals(LEAP)?".list":null;if(suffix==null)throw new IllegalArgumentException("Unknown dataset type");return new File(new File(context.getFilesDir(),"astronomy"),kind+suffix);}
private static SharedPreferences prefs(Context c){return c.getSharedPreferences("astronomy_data",Context.MODE_PRIVATE);}
public static synchronized void migrateLegacy(Context c){File current=file(c,SPK),old=new File(c.getFilesDir(),"de440s.bsp");if(current.exists()||!old.isFile())return;try{String prior=c.getSharedPreferences("ephemeris",0).getString("sha256","");if(prior.isEmpty()||!hash(old).equalsIgnoreCase(prior))return;try(SolarAlarmEphemeris e=new SolarAlarmEphemeris(old)){}current.getParentFile().mkdirs();if(!old.renameTo(current))return;prefs(c).edit().putString(SPK+".sha256",prior).putString(SPK+".name","de440s.bsp").putString(SPK+".origin","existing installation").putLong(SPK+".installed",System.currentTimeMillis()).commit();}catch(Exception ignored){}}
public static boolean ready(Context c,String kind){if(kind.equals(SPK))migrateLegacy(c);return file(c,kind).isFile()&&!prefs(c).getString(kind+".sha256","").isEmpty();}
public static boolean complete(Context c){for(String type:TYPES)if(!ready(c,type))return false;return true;}
public static String hash(File f) throws Exception {MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new BufferedInputStream(new FileInputStream(f))){byte[] block=new byte[131072];int n;while((n=in.read(block))>=0)if(n>0)digest.update(block,0,n);}StringBuilder out=new StringBuilder();for(byte b:digest.digest())out.append(String.format(Locale.US,"%02x",b&255));return out.toString();}
public static void verify(Context c,String kind) throws Exception {File f=file(c,kind);if(!ready(c,kind))throw new IOException(title(kind)+" not loaded");String expected=prefs(c).getString(kind+".sha256","");if(!MessageDigest.isEqual(expected.getBytes("US-ASCII"),hash(f).getBytes("US-ASCII")))throw new IOException(title(kind)+" checksum mismatch");validate(kind,f);}
private static void validate(String kind,File file) throws Exception {if(kind.equals(SPK)){try(SolarAlarmEphemeris ephemeris=new SolarAlarmEphemeris(file)){}return;}SolarAlarmTiming.validate(kind,file);}
public static synchronized String install(Context c,String kind,InputStream in,String sourceName,String origin) throws Exception {File target=file(c,kind),directory=target.getParentFile();if(!directory.isDirectory()&&!directory.mkdirs())throw new IOException("Cannot create data directory");File staging=File.createTempFile("incoming_",".part",directory);long max=kind.equals(SPK)?95000000L:kind.equals(EOP)?12000000L:1000000L;try{long count=0;try(FileOutputStream out=new FileOutputStream(staging)){byte[] bytes=new byte[131072];int n;while((n=in.read(bytes))!=-1){count+=n;if(count>max)throw new IOException("Dataset exceeds size limit");out.write(bytes,0,n);}out.getFD().sync();}if(count<1)throw new IOException("Dataset is empty");validate(kind,staging);String sha=hash(staging);if(!staging.renameTo(target))throw new IOException("Could not activate validated dataset");boolean saved=prefs(c).edit().putString(kind+".sha256",sha).putString(kind+".name",sourceName).putString(kind+".origin",origin).putLong(kind+".installed",System.currentTimeMillis()).commit();if(!saved)throw new IOException("Dataset activated but metadata could not be stored");SolarAlarmTiming.invalidate();return sha;}finally{staging.delete();}}
public static String importUri(Context c,String kind,Uri uri,String name) throws Exception {try(InputStream stream=c.getContentResolver().openInputStream(uri)){if(stream==null)throw new IOException("Unable to read selected file");return install(c,kind,stream,name,"user file");}}
public static String download(Context c,String kind) throws Exception {String[] candidates=kind.equals(EOP)?new String[]{url(kind),"https://www.simplespacedata.org/eop/usno/finals2000a_all/latest/finals2000A.all"}:new String[]{url(kind)};Exception failure=null;for(String endpoint:candidates){HttpURLConnection conn=null;try{conn=(HttpURLConnection)new URL(endpoint).openConnection();conn.setConnectTimeout(20000);conn.setReadTimeout(60000);conn.setInstanceFollowRedirects(true);conn.setRequestProperty("User-Agent","SolarElevationAlarm-Test/1.0");if(conn.getResponseCode()!=HttpURLConnection.HTTP_OK)throw new IOException("HTTP "+conn.getResponseCode());try(InputStream stream=new BufferedInputStream(conn.getInputStream())){return install(c,kind,stream,defaultName(kind),"default download: "+endpoint);}}catch(Exception ex){failure=ex;}finally{if(conn!=null)conn.disconnect();}}throw new IOException("All default sources failed for "+title(kind),failure);}
public static String summary(Context c,String kind){if(!ready(c,kind))return "Not loaded";return prefs(c).getString(kind+".name","local file")+" · loaded";}
public static String diagnostics(Context c){StringBuilder out=new StringBuilder();SharedPreferences p=prefs(c);for(String kind:TYPES){out.append(title(kind)).append(": ").append(ready(c,kind)?"loaded":"missing").append('\n');if(ready(c,kind)){out.append("  Local path: ").append(file(c,kind).getAbsolutePath()).append('\n').append("  Source file: ").append(p.getString(kind+".name","")).append('\n').append("  Origin: ").append(p.getString(kind+".origin","")).append('\n').append("  SHA-256: ").append(p.getString(kind+".sha256","")).append('\n').append("  Imported at epoch ms: ").append(p.getLong(kind+".installed",0)).append('\n');}}try{out.append(SolarAlarmTiming.diagnostics(c));}catch(Exception ex){out.append("Timing dataset diagnostics: ").append(ex.getMessage()).append('\n');}return out.toString();}
private SolarAlarmDatasets(){}
}
